/* ============================================================
   ZONES — the opening chooser.

   Zones are STATES. Fishing regulations are written by states, and the
   state line is the one border that actually changes what you may do, so
   it is the border the chooser draws. National parks keep their own NPS
   boundary and sit on top of the state they are in, because their rules
   are their own — Yellowstone spans three states and answers to none of
   them.

   This replaced a Voronoi tiling of river clusters. Every region had a
   neighbour there, but the borders were invented: a bisector halfway
   between two river clusters means nothing to an angler.

   REGION_LABELS are the named places that cross state lines — the
   Driftless above all, one landscape across four states and four
   rulebooks. They fade in as you zoom (see REGION_LABEL_ZOOM in app.js)
   and are labels only: nothing to tap, nothing to divide.

   `rings[0]` is the outer boundary; any further rings are holes. `short`
   is the name used when a zone is too small at the current zoom to carry
   the full one. `count` is rivers mapped there, and a park's rivers count
   to the park rather than to the state it sits in.
   Regenerate with zones2.py in the scratchpad.
   ============================================================ */
